def get_category(label: str) -> str:
    """Return category for a label, or 'Unknown'. Case-insensitive."""
    if not label:
        return "Unknown"
    label = label.lower().strip()
    lookup = {k.lower(): v for k, v in WASTE_DB.items()}
    if label in lookup:
        return lookup[label][0]
    for key, (cat, _) in lookup.items():
        if key in label or label in key:
            return cat
    for cat in CATEGORIES:
        if label == cat.lower():
            return cat
    return "Unknown"


def get_fallback_tip(label: str) -> str:
    """Rule-based tip from DB. Used if LLM fails."""
    if not label:
        return "Check your local waste guidelines for disposal."
    label = label.lower().strip()
    if label in WASTE_DB:
        return WASTE_DB[label][1]
    for key, (_, tip) in WASTE_DB.items():
        if key in label or label in key:
            return tip
    return f"Dispose of '{label}' according to your local guidelines."


def all_items() -> list:
    """Return all item names for benchmark loops."""
    return list(WASTE_DB.keys())



